    ClassDefiningFunctionNode(JsName name, Node node, Node parent,
        Node gramps) {
      super(name, node, parent, gramps);
      Preconditions.checkState(node.isCall());
    }

    @Override
    public void remove() {
      Preconditions.checkState(node.isCall());
      if (parent.isExprResult()) {
